from collections import deque


def maxWaitMinutes(grid):
    rows, cols = len(grid), len(grid[0])
    INF = 10 ** 18
    fire = [[INF] * cols for _ in range(rows)]
    q = deque()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                fire[r][c] = 0
                q.append((r, c))
    while q:
        y, x = q.popleft()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == 0 and fire[ny][nx] == INF:
                fire[ny][nx] = fire[y][x] + 1
                q.append((ny, nx))

    def ok(w):
        if fire[0][0] <= w:
            return False
        dist = [[-1] * cols for _ in range(rows)]
        dist[0][0] = 0
        q = deque([(0, 0)])
        while q:
            y, x = q.popleft()
            nd = dist[y][x] + 1
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == 0 and dist[ny][nx] == -1:
                    if ny == rows - 1 and nx == cols - 1:
                        if w + nd <= fire[ny][nx]:
                            return True
                    elif w + nd < fire[ny][nx]:
                        dist[ny][nx] = nd
                        q.append((ny, nx))
        return False

    if not ok(0):
        return -1
    hi = rows * cols + 2
    if ok(hi):
        return 1000000000
    lo = 0
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid
    return lo
